112	        for (int codeLength = Math.min(3, digits.length() - 1); codeLength >= 1; codeLength--) {
113	            String candidate = digits.substring(0, codeLength);
114	            if (KNOWN_COUNTRY_CODES.contains(candidate)) {
115	                countryCode = candidate;
116	                national = digits.substring(codeLength);
117	                break;
118	            }
119	        }
120	        StringBuilder grouped = new StringBuilder();
121	        for (int i = 0; i < national.length(); i++) {
122	            if (i > 0 && i % 3 == 0) {
123	                grouped.append(' ');
124	            }
125	            grouped.append(national.charAt(i));
126	        }
127	        return "+" + countryCode + " " + grouped;
128	    }
129	
130	    /**
131	     * Compute the owner's check digit: a single Luhn check digit (0-9) over the digits contained in
132	     * the customerCode. Returns null when no customerCode has been assigned so owners without a code
133	     * serialize cleanly.
134	     */
135	    default Integer checkDigit(Owner owner) {
136	        String customerCode = owner.getCustomerCode();
137	        if (customerCode == null) {
138	            return null;
139	        }
140	        int sum = 0;
141	        boolean dbl = true;
142	        for (int i = customerCode.length() - 1; i >= 0; i--) {
143	            char c = customerCode.charAt(i);
144	            if (c < '0' || c > '9') {
145	                continue;
146	            }
147	            int d = c - '0';
148	            if (dbl) {
149	                d *= 2;
150	                if (d > 9) {
151	                    d -= 9;
152	                }
153	            }
154	            sum += d;
155	            dbl = !dbl;
156	        }
157	        return (10 - (sum % 10)) % 10;
158	    }
