160	    /**
161	     * Derive the owner's identity key, the single value into which all duplicate detection is
162	     * consolidated: {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two
163	     * owners are duplicates only when their whole identity keys are equal. A null email or
164	     * householdId contributes an empty segment.
165	     */
166	    default String identityKey(Owner owner) {
167	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
168	        String email = owner.getEmail() == null ? "" : owner.getEmail();
169	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
170	        return telephone + "|" + email + "|" + householdId;
171	    }
172	
173	    /**
174	     * Determine the owner's preferred contact channel: 'EMAIL' when an email address is present,
175	     * otherwise 'PHONE'.
