178	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
179	        return hasEmail ? "EMAIL" : "PHONE";
180	    }
181	
182	    /**
183	     * Build the owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is
184	     * the last two digits of the registrationDate year. Returns null when either source field is
185	     * absent so owners without an assigned code or registration date serialize cleanly.
186	     */
187	    default String membershipNumber(Owner owner) {
188	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
189	            return null;
190	        }
191	        return String.format("%s-M%02d", owner.getCustomerCode(),
192	            owner.getRegistrationDate().getYear() % 100);
193	    }
194	
195	    /**
196	     * Compute the owner's membership points. Starts at 0; add 2 when an email address is present;
197	     * add 1 when the owner has no namesakes (namesakeCount is 0); add 2 for a household of 3 or more
198	     * (householdSize); add 3 for tenure of more than 365 days, measured from the registrationDate to
199	     * the current date. Because a newly created owner has zero tenure, a new owner never earns the
200	     * tenure points.
201	     */
202	    default Integer membershipPoints(Owner owner) {
203	        int points = 0;
204	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
205	        if (hasEmail) {
206	            points += 2;
207	        }
208	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
209	        if (noNamesakes) {
210	            points += 1;
211	        }
212	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
213	            points += 2;
214	        }
215	        if (owner.getRegistrationDate() != null && java.time.temporal.ChronoUnit.DAYS.between(
216	                owner.getRegistrationDate(), java.time.LocalDate.now()) > 365) {
217	            points += 3;
218	        }
219	        return points;
220	    }
221	
222	    /**
223	     * Determine the owner's numeric membership level, derived from membershipPoints: 1 for 0-1
224	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
225	     */
226	    default Integer membershipLevel(Owner owner) {
227	        int points = membershipPoints(owner);
228	        if (points <= 1) {
229	            return 1;
230	        }
231	        if (points <= 3) {
232	            return 2;
233	        }
234	        if (points <= 5) {
235	            return 3;
236	        }
237	        return 4;
238	    }
239	
240	    /**
241	     * The fixed city-to-region table used to derive an owner's locality when the postcode is absent
242	     * or falls in no known range.
243	     */
244	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
245	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
246	
247	    /**
248	     * Region -&gt; inclusive 4-digit postcode range {low, high}: NSW 2000-2099, VIC 3000-3099,
249	     * QLD 4000-4099.
250	     */
251	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
252	        "NSW", new int[] {2000, 2099},
253	        "VIC", new int[] {3000, 3099},
254	        "QLD", new int[] {4000, 4099});
255	
256	    /**
257	     * Derive the owner's locality (canonical region), preferring the postcode: look up the region by
258	     * postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only fall back to the
259	     * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is
260	     * absent or in no known range. Returns 'UNKNOWN' when neither source resolves a region.
261	     */
262	    default String locality(Owner owner) {
263	        String postcode = owner.getPostcode();
264	        if (postcode != null && postcode.matches("\\d{4}")) {
265	            int value = Integer.parseInt(postcode);
266	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
267	                int[] range = entry.getValue();
268	                if (value >= range[0] && value <= range[1]) {
269	                    return entry.getKey();
270	                }
271	            }
272	        }
273	        String city = owner.getCity();
274	        if (city == null) {
275	            return "UNKNOWN";
276	        }
277	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
278	    }
279	
280	    /**
281	     * The fixed region-to-timezone table used to derive an owner's timezone from its locality:
282	     * NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane.
283	     */
284	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
285	        "NSW", "Australia/Sydney",
286	        "VIC", "Australia/Melbourne",
287	        "QLD", "Australia/Brisbane");
